/bin/bash -lc "python - <<'PY'
import numpy as np
h=1.;d=.16;s=.66;g=18.;m=np.array([1,1,10.])
def angles(q):
 b=q+np.arcsin(s*np.cos(q)-d)
 a=b+np.arcsin(s*np.cos(b)-d)
 return np.array([a,b,q])
def derivatives(q):
 e=1e-5
 return (angles(q+e)-angles(q-e))/(2*e)
r=derivatives(0);I=(1+d*d)/3
q=0.;v=1.65*(r[0]**2+r[1]**2)/(r[0]**2+r[1]**2+10)
print('angles',angles(0),'deriv',r,'initialvelocity',v)
mx=0
for it in range(3000):
 r=derivatives(q);A=I*np.sum(m*r*r);Ap=(I*np.sum(m*derivatives(q+1e-4)**2)-I*np.sum(m*derivatives(q-1e-4)**2))/(2e-4)
 a=(np.sum(m*g/2*(np.sin(angles(q))-d*np.cos(angles(q)))*r)-.5*Ap*v*v)/A-1.2*v
 v+=a*.001;q+=v*.001
 if q<0:q=0;v=max(0,-v*.08)
 mx=max(mx,q)
 if it%100==0:print(round(it*.001,2),round(q,5),round(v,4))
print('max',mx)
PY"
